 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Use the visible solid-color rows, in their observed order, as a cyclic
    # motif. Fill only blank rows; leave nonblank source rows unchanged.
    colors = []
    for row in grid:
        if all(v == row[0] for v in row) and row[0] != 0:
            colors.append(row[0])
    if len(colors) < 2:
        return [row[:] for row in grid]
    first = next(i for i, row in enumerate(grid) if row[0] != 0)
    phase = colors.index(grid[first][0])
    out = []
    for i, row in enumerate(grid):
        if all(v == 0 for v in row):
            out.append([colors[(phase + i - first) % len(colors)]] * w)
        else:
            out.append(row[:])
    return out

if __name__ == '__main__':
    sample = [[0]*5, [9]*5, [4]*5, [0]*5, [0]*5]
    print(transform(sample))
